def read_all(data, limit):
    requests_made, collected, offset = 0, [], 0
    while True:
        batch = data[offset:offset + limit]
        requests_made += 1
        collected.extend(batch)
        if len(batch) < limit:
            break
        offset += limit
    return requests_made, len(collected)

print(*read_all(list(range(20)), 10))
print(*read_all(list(range(25)), 5))

