def get_batch(cursor):
    start = int(cursor or 0)
    end = start + 4
    return {"data": list(range(start, min(end, 10))), "next_cursor": str(end) if end < 10 else None}

def iter_cursor(get_batch):
    cursor = ""
    while cursor is not None:
        body = get_batch(cursor)
        yield from body["data"]
        cursor = body["next_cursor"]

print(list(iter_cursor(get_batch)))

