independent.solution:
DATA = list(range(1, 24))

def get_page(page, page_size):
    pages = -(-len(DATA) // page_size)
    return {"data": DATA[(page - 1) * page_size:page * page_size], "page": page, "total_pages": pages}

def broken_get_page(page, page_size):
    return {"data": list(range(5)), "page": page, "total_pages": 999}

def iter_pages(get_page, page_size, max_pages):
    for page in range(1, max_pages + 1):
        body = get_page(page, page_size)
        yield from body["data"]
        if not body["data"] or page >= body["total_pages"]:
            return
    raise RuntimeError("max_pages exceeded")

print(len(list(iter_pages(get_page, 10, 10))))
got = 0
try:
    for _ in iter_pages(broken_get_page, 10, 4):
        got += 1
except RuntimeError as err:
    print(got, err)
